target.css:
:root {
  --ink: #252133;
  --muted: #706b81;
  --paper: #fffdf8;
  --line: #e5dfd3;
  --violet: #7454b8;
  --violet-soft: #eee9fa;
  --plum: #3f285c;
  --coral: #d86c57;
  --coral-soft: #fff0eb;
  --mint: #3c9b78;
  --mint-soft: #e8f6ef;
  --gold: #d99a35;
}

* {
  box-sizing: border-box;
}

.press-card {
  width: 500px;
  overflow: hidden;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 18px;
}

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 13px 16px 12px;
  border-bottom: 1px solid var(--line);
}

.title-group p,
.title-group h1,
.press-meta p,
.footer p {
  margin: 0;
}

.eyebrow,
.meta-label,
.metric-label {
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.09em;
}

.title-group h1 {
  margin-top: 3px;
  color: var(--plum);
  font-size: 20px;
  line-height: 1;
  letter-spacing: -0.03em;
}

.status {
  padding: 5px 8px;
  color: var(--mint);
  background: var(--mint-soft);
  border-radius: 999px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.08em;
}

.content {
  display: grid;
  grid-template-columns: 1.1fr 1.55fr;
  gap: 14px;
  padding: 14px 16px;
}

.record-panel {
  display: flex;
  align-items: center;
  gap: 11px;
  min-width: 0;
}

.disc {
  display: grid;
  flex: 0 0 104px;
  place-items: center;
  width: 104px;
  height: 104px;
  margin: 0;
  background: var(--plum);
  border: 11px solid var(--violet);
  border-radius: 50%;
}

.disc-center {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  color: var(--paper);
  background: var(--coral);
  border: 3px solid var(--paper);
  border-radius: 50%;
  font-size: 9px;
  font-weight: 800;
  line-height: 1.05;
  text-align: center;
}

.press-meta {
  display: flex;
  flex-direction: column;
  gap: 5px;
  min-width: 0;
}

.press-meta strong {
  color: var(--plum);
  font-size: 13px;
  line-height: 1.15;
}

.press-meta p:not(.meta-label) {
  color: var(--muted);
  font-size: 11px;
  line-height: 1.25;
}

.cycle-chip {
  width: fit-content;
  padding: 4px 6px;
  color: var(--violet);
  background: var(--violet-soft);
  border-radius: 5px;
  font-size: 10px;
  font-weight: 700;
}

.metrics {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 7px;
}

.metric {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  min-width: 0;
  padding: 10px 8px 8px;
  border: 1px solid var(--line);
  border-radius: 10px;
}

.metric-hot {
  background: var(--coral-soft);
  border-color: var(--coral);
}

.metric-cool {
  background: var(--mint-soft);
  border-color: var(--mint);
}

.metric-neutral {
  background: var(--violet-soft);
  border-color: var(--violet);
}

.metric strong {
  margin-top: 7px;
  color: var(--ink);
  font-size: 19px;
  line-height: 1;
  letter-spacing: -0.05em;
}

.metric strong span {
  margin-left: 1px;
  font-size: 10px;
  letter-spacing: 0;
}

.metric small {
  margin-top: 7px;
  color: var(--muted);
  font-size: 9px;
  line-height: 1.15;
}

.footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px;
  background: var(--violet-soft);
  border-top: 1px solid var(--line);
}

.footer p {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--muted);
  font-size: 11px;
}

.dot {
  width: 7px;
  height: 7px;
  background: var(--gold);
  border-radius: 50%;
}

.footer button {
  padding: 7px 10px;
  color: var(--paper);
  background: var(--violet);
  border: 0;
  border-radius: 7px;
  font-size: 11px;
  font-weight: 700;
}

